SELECT * FROM menu_recipe
WHERE is_deleted = 0 AND group_id = #{groupId}
AND (original_text IS NOT NULL
     OR EXISTS (SELECT 1 FROM menu_section s
                WHERE s.recipe_id = menu_recipe.id AND s.is_deleted = 0))

    AND status = #{status}


    AND recipe_date >= #{dateFrom}


    AND recipe_date <= #{dateTo}


    AND (title LIKE CONCAT('%', #{keyword}, '%')
         OR id IN (SELECT recipe_id FROM menu_item
                   WHERE is_deleted = 0 AND name LIKE CONCAT('%', #{keyword}, '%')))

ORDER BY recipe_date DESC, created_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM menu_recipe
WHERE is_deleted = 0 AND group_id = #{groupId}
AND (original_text IS NOT NULL
     OR EXISTS (SELECT 1 FROM menu_section s
                WHERE s.recipe_id = menu_recipe.id AND s.is_deleted = 0))

    AND status = #{status}


    AND recipe_date >= #{dateFrom}


    AND recipe_date <= #{dateTo}


    AND (title LIKE CONCAT('%', #{keyword}, '%')
         OR id IN (SELECT recipe_id FROM menu_item
                   WHERE is_deleted = 0 AND name LIKE CONCAT('%', #{keyword}, '%')))

